"""User-grain analytics, ordered funnels, sessions and retention."""
from _draft_helpers import topic

S = """
CREATE TABLE member(id INTEGER PRIMARY KEY,signup TEXT);
INSERT INTO member VALUES(1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
CREATE TABLE event(id INTEGER PRIMARY KEY,member_id INTEGER,at TEXT,kind TEXT);
INSERT INTO event VALUES
 (1,1,'2026-01-01 09:00:00','view'),(2,1,'2026-01-01 09:01:00','cart'),
 (3,1,'2026-01-01 09:02:00','pay'),(4,1,'2026-01-02 09:00:00','view'),(5,1,'2026-01-04 09:00:00','view'),
 (6,2,'2026-01-01 10:00:00','view'),(7,2,'2026-01-03 09:00:00','cart'),(8,2,'2026-01-03 09:01:00','view'),
 (9,3,'2026-01-02 10:00:00','view'),(10,3,'2026-01-02 10:01:00','pay'),(11,3,'2026-01-03 10:00:00','view'),
 (12,4,'2026-01-03 11:00:00','pay'),(13,1,'2026-01-01 09:03:00','view');
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"cohorts",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(217,"daily-active-vs-events","日活人数与事件次数的粒度区别",["DAU","COUNT DISTINCT","重复事件"],
   "一月一日有五条事件，但只有用户 1、2 两人活跃。按日期同时输出事件数和不同用户数，四天分别为 5/2、3/2、4/3、1/1。重复 view 不应抬高日活，但会影响事件量。",
   "SELECT date(at),count(*),count(DISTINCT member_id) FROM event GROUP BY date(at) ORDER BY date(at);","2026-01-01|5|2\n2026-01-02|3|2\n2026-01-03|4|3\n2026-01-04|1|1",
   ["事件数不能当作活跃用户数。","日期分桶应先统一时区。"],
   ("统计整个观察期的去重活跃人数。","跨天再次去重。","SELECT count(DISTINCT member_id) FROM event;","4"),
   ("统计一月一日 view 事件数和浏览人数。","事件类型过滤后分别计数。","SELECT count(*),count(DISTINCT member_id) FROM event WHERE date(at)='2026-01-01' AND kind='view';","3|2")),
 T(218,"cohort-size","注册 cohort 大小独立于行为表",["cohort","注册分母","LEFT JOIN"],
   "cohort 分母来自 member 注册表，不能用当天产生行为的人数代替。三天注册人数为 2、1、1，即使某用户没有目标行为，也必须保留在后续转化率分母。本例以日期为 cohort 粒度。",
   "SELECT signup,count(*) FROM member GROUP BY signup ORDER BY signup;","2026-01-01|2\n2026-01-02|1\n2026-01-03|1",
   ["从事件表推断注册人数会漏掉静默用户。","注册日与事件日应使用相同时间标准。"],
   ("求每个用户首次事件日。","按 member_id 取最早时间。","SELECT member_id,date(min(at)) FROM event GROUP BY member_id ORDER BY member_id;","1|2026-01-01\n2|2026-01-01\n3|2026-01-02\n4|2026-01-03"),
   ("找出从未浏览 view 的注册用户。","NOT EXISTS 只检查目标行为。","SELECT id FROM member m WHERE NOT EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND e.kind='view') ORDER BY id;","4")),
 T(219,"next-day-retention","次日留存按注册分母计算",["次日留存","EXISTS","比例"],
   "判断注册后一天是否至少有一次事件，EXISTS 保证一位用户只贡献一次。首日 cohort 两人中用户 1 回来，留存 50%；第二日用户 3 回来为 100%；第三日用户 4 未回来为 0%。本观察期足以覆盖三组次日。",
   "SELECT m.signup,count(*),sum(EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND date(e.at)=date(m.signup,'+1 day'))),round(100.0*sum(EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND date(e.at)=date(m.signup,'+1 day')))/count(*),1) FROM member m GROUP BY m.signup ORDER BY m.signup;","2026-01-01|2|1|50.0\n2026-01-02|1|1|100.0\n2026-01-03|1|0|0.0",
   ["未观察到次日的 cohort 应标为未成熟，不能直接算零。","留存事件口径需要明确，本课使用任意事件。"],
   ("列出发生次日留存的用户 id。","使用 EXISTS 检查注册加一天。","SELECT m.id FROM member m WHERE EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND date(e.at)=date(m.signup,'+1 day')) ORDER BY m.id;","1\n3"),
   ("计算一月一日 cohort 的第三日偏移活跃人数。","偏移 3 指一月四日。","SELECT count(*) FROM member m WHERE signup='2026-01-01' AND EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND date(e.at)=date(m.signup,'+3 days'));","1")),
 T(220,"retention-long-table","留存矩阵先输出长表",["cohort 矩阵","天偏移","去重"],
   "先去重用户活跃日期，再计算活跃日减注册日作为 offset，最后按 cohort、offset 计人数。长表保留稀疏结构，便于界面按需透视。首日 cohort 在偏移 0 有两人，其后 1、2、3 各一人。",
   "WITH active AS(SELECT DISTINCT member_id,date(at) d FROM event) SELECT m.signup,CAST(julianday(a.d)-julianday(m.signup) AS INTEGER) offset,count(*) FROM member m JOIN active a ON a.member_id=m.id GROUP BY m.signup,offset ORDER BY m.signup,offset;","2026-01-01|0|2\n2026-01-01|1|1\n2026-01-01|2|1\n2026-01-01|3|1\n2026-01-02|0|1\n2026-01-02|1|1\n2026-01-03|0|1",
   ["不先按用户日期去重会把事件次数当留存人数。","缺少格子与明确零值应由展示层结合成熟度区分。"],
   ("计算全体用户贡献的活跃用户日数。","不同用户日期键计数。","SELECT count(*) FROM(SELECT DISTINCT member_id,date(at) FROM event);","8"),
   ("返回注册当天活跃的不同用户数。","事件日期等于注册日期。","SELECT count(DISTINCT m.id) FROM member m JOIN event e ON e.member_id=m.id WHERE date(e.at)=m.signup;","4")),
 T(221,"ordered-funnel","有序漏斗要求浏览加购支付先后成立",["漏斗","时间顺序","相关最小值"],
   "先取首次 view，再取其后的首次 cart，再取 cart 后的 pay。结果只有用户 1 完整走通，用户 3 虽有支付却跳过加购，用户 4 没有浏览入口。按事件是否出现做集合交集无法保证先后顺序。",
   "WITH v AS(SELECT member_id,min(at) t FROM event WHERE kind='view' GROUP BY member_id),c AS(SELECT v.member_id,min(e.at) t FROM v JOIN event e ON e.member_id=v.member_id AND e.kind='cart' AND e.at>=v.t GROUP BY v.member_id) SELECT c.member_id,min(e.at) FROM c JOIN event e ON e.member_id=c.member_id AND e.kind='pay' AND e.at>=c.t GROUP BY c.member_id ORDER BY c.member_id;","1|2026-01-01 09:02:00",
   ["时间相同的事件还可能需要序号确定先后。","同一用户的多轮漏斗需明确配对窗口。"],
   ("返回存在 view 后 cart 的用户。","先取首个 view，再找后续 cart。","WITH v AS(SELECT member_id,min(at) t FROM event WHERE kind='view' GROUP BY member_id) SELECT DISTINCT v.member_id FROM v JOIN event e ON e.member_id=v.member_id AND e.kind='cart' AND e.at>=v.t ORDER BY v.member_id;","1\n2"),
   ("列出支付过但从未加购的用户。","pay 存在，cart 不存在。","SELECT DISTINCT p.member_id FROM event p WHERE p.kind='pay' AND NOT EXISTS(SELECT 1 FROM event c WHERE c.member_id=p.member_id AND c.kind='cart') ORDER BY p.member_id;","3\n4")),
 T(222,"funnel-step-counts","漏斗步骤人数与原始事件人数分开",["漏斗分母","条件集合","转化"],
   "先构造每步合格用户集合，浏览 3 人，浏览后加购 2 人，前两步后支付 1 人。三条查询共享顺序约束，而不是分别 COUNT 各类事件。这样步骤人数单调不增，能计算清楚每一段流失。",
   "WITH v AS(SELECT member_id,min(at) t FROM event WHERE kind='view' GROUP BY member_id),c AS(SELECT v.member_id,min(e.at) t FROM v JOIN event e ON e.member_id=v.member_id AND e.kind='cart' AND e.at>=v.t GROUP BY v.member_id),p AS(SELECT c.member_id FROM c JOIN event e ON e.member_id=c.member_id AND e.kind='pay' AND e.at>=c.t GROUP BY c.member_id) SELECT '1_view',count(*) FROM v UNION ALL SELECT '2_cart',count(*) FROM c UNION ALL SELECT '3_pay',count(*) FROM p;","1_view|3\n2_cart|2\n3_pay|1",
   ["分别统计 pay 用户会得到 3，而完整漏斗只有 1。","漏斗人数需要共同观察范围。"],
   ("计算原始支付用户数作为对照。","COUNT DISTINCT 支付用户。","SELECT count(DISTINCT member_id) FROM event WHERE kind='pay';","3"),
   ("返回发生过加购的不同用户数。","重复加购也只计一次。","SELECT count(DISTINCT member_id) FROM event WHERE kind='cart';","2")),
 T(223,"session-boundaries","按三十分钟空闲阈值切分会话",["会话化","LAG","空闲阈值"],
   "先用 LAG 取同用户前一事件时间，首次事件或间隔超过 1800 秒记作新会话，再按用户求和。用户 1、2、3、4 分别有 3、2、2、1 个会话。阈值是产品约定，不能通过跨日简单切割代替。",
   "WITH r AS(SELECT *,lag(at) OVER(PARTITION BY member_id ORDER BY at,id) prior FROM event) SELECT member_id,sum(prior IS NULL OR unixepoch(at)-unixepoch(prior)>1800) FROM r GROUP BY member_id ORDER BY member_id;","1|3\n2|2\n3|2\n4|1",
   ["先筛掉某些事件会改变空闲间隔。","恰好三十分钟是否切分要明确大于还是大于等于。"],
   ("列出用户 1 的新会话起始事件 id。","LAG 后用阈值过滤。","WITH r AS(SELECT id,at,lag(at) OVER(ORDER BY at,id) prior FROM event WHERE member_id=1) SELECT id FROM r WHERE prior IS NULL OR unixepoch(at)-unixepoch(prior)>1800 ORDER BY at,id;","1\n4\n5"),
   ("统计全部用户会话总数。","先按全用户 LAG，再累计边界。","WITH r AS(SELECT *,lag(at) OVER(PARTITION BY member_id ORDER BY at,id) prior FROM event) SELECT sum(prior IS NULL OR unixepoch(at)-unixepoch(prior)>1800) FROM r;","8")),
 T(224,"session-length","会话编号后计算时长与事件量",["累计分组","会话时长","事件密度"],
   "LAG 得到边界标记后，再对标记累计产生 session_id，最后按用户与会话聚合。用户 1 首会话四条事件、跨度 180 秒，后两会话各一条、跨度 0。单事件会话为零跨度，不代表用户停留时间被完整测量。",
   "WITH r AS(SELECT *,lag(at) OVER(PARTITION BY member_id ORDER BY at,id) prior FROM event),s AS(SELECT *,sum(prior IS NULL OR unixepoch(at)-unixepoch(prior)>1800) OVER(PARTITION BY member_id ORDER BY at,id ROWS UNBOUNDED PRECEDING) sid FROM r) SELECT sid,count(*),unixepoch(max(at))-unixepoch(min(at)) FROM s WHERE member_id=1 GROUP BY sid ORDER BY sid;","1|4|180\n2|1|0\n3|1|0",
   ["会话最后事件后的停留时间不在数据内。","窗口函数不能在同一层直接嵌套，需分 CTE。"],
   ("求用户 1 首日事件跨度分钟数。","同一天 MAX-MIN。","SELECT (unixepoch(max(at))-unixepoch(min(at)))/60 FROM event WHERE member_id=1 AND date(at)='2026-01-01';","3"),
   ("统计每用户全部事件数。","保留重复事件作为事件量。","SELECT member_id,count(*) FROM event GROUP BY member_id ORDER BY member_id;","1|6\n2|3\n3|3\n4|1")),
 T(225,"consecutive-active-streak","连续活跃日用岛屿分组",["gaps and islands","ROW_NUMBER","连续天"],
   "用户日先去重，再用 JULIANDAY(日)-ROW_NUMBER 构造连续段键。用户 1 和 3 的最长连续活跃为 2 天，用户 2 和 4 为 1 天。没有先按日去重，首日多条事件会破坏连续段编号。",
   "WITH d AS(SELECT DISTINCT member_id,date(at) day FROM event),r AS(SELECT *,julianday(day)-row_number() OVER(PARTITION BY member_id ORDER BY day) g FROM d),s AS(SELECT member_id,g,count(*) len FROM r GROUP BY member_id,g) SELECT member_id,max(len) FROM s GROUP BY member_id ORDER BY member_id;","1|2\n2|1\n3|2\n4|1",
   ["重复用户日必须在开窗前去掉。","连续自然日与连续工作日需要不同日历序号。"],
   ("列出用户 1 每段连续活跃的起止日。","相同岛屿键分组。","WITH d AS(SELECT DISTINCT date(at) day FROM event WHERE member_id=1),r AS(SELECT day,julianday(day)-row_number() OVER(ORDER BY day) g FROM d) SELECT min(day),max(day),count(*) FROM r GROUP BY g ORDER BY min(day);","2026-01-01|2026-01-02|2\n2026-01-04|2026-01-04|1"),
   ("列出活跃自然日达到三天的用户。","COUNT DISTINCT 日期。","SELECT member_id FROM event GROUP BY member_id HAVING count(DISTINCT date(at))>=3 ORDER BY member_id;","1")),
 T(226,"reactivation-gaps","识别跨缺口回流的活跃用户日",["回流","LAG 日期","缺口"],
   "先把事件变为不同用户日，再比较相邻活跃日期。缺口超过一天的回流为用户 1 的一月四日、用户 2 的一月三日，均相隔两天。首次出现没有前日，属于首次活跃而非回流。",
   "WITH d AS(SELECT DISTINCT member_id,date(at) day FROM event),r AS(SELECT *,lag(day) OVER(PARTITION BY member_id ORDER BY day) prior FROM d) SELECT member_id,day,CAST(julianday(day)-julianday(prior) AS INTEGER) FROM r WHERE julianday(day)-julianday(prior)>1 ORDER BY member_id,day;","1|2026-01-04|2\n2|2026-01-03|2",
   ["回流阈值是业务定义，不能与次日留存混淆。","观察期前活跃未知会影响首次与回流分类。"],
   ("统计有回流日的不同用户数。","外层 COUNT DISTINCT。","WITH d AS(SELECT DISTINCT member_id,date(at) day FROM event),r AS(SELECT *,lag(day) OVER(PARTITION BY member_id ORDER BY day) p FROM d) SELECT count(DISTINCT member_id) FROM r WHERE julianday(day)-julianday(p)>1;","2"),
   ("输出用户 2 两次活跃之间的缺失日数。","先取日期，间隔天数再减一。","SELECT CAST(julianday(date(max(at)))-julianday(date(min(at))) AS INTEGER)-1 FROM event WHERE member_id=2;","1")),
 T(227,"activation-window","注册后二十四小时内的目标激活",["激活窗口","半开时间范围","EXISTS"],
   "目标激活定义为注册日起 24 小时内至少一次 view，三组激活数为 2、1、0。用户 4 虽然当天支付，却没有 view，所以不满足本课的激活定义。把注册日期转 DATETIME 后再加一天，避免文本格式比较混乱。",
   "SELECT signup,sum(EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND e.kind='view' AND e.at>=datetime(m.signup) AND e.at<datetime(m.signup,'+1 day'))) FROM member m GROUP BY signup ORDER BY signup;","2026-01-01|2\n2026-01-02|1\n2026-01-03|0",
   ["只有日期的注册时间不能还原真实注册后精确 24 小时。","激活是产品事件定义，不是所有事件通用别名。"],
   ("找出未按该定义激活的用户。","NOT EXISTS 同一窗口 view。","SELECT m.id FROM member m WHERE NOT EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND e.kind='view' AND e.at>=datetime(m.signup) AND e.at<datetime(m.signup,'+1 day')) ORDER BY m.id;","4"),
   ("计算首日 cohort 激活率。","两个成员均发生 view。","SELECT round(100.0*sum(EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND e.kind='view' AND date(e.at)=m.signup))/count(*),1) FROM member m WHERE signup='2026-01-01';","100.0")),
 T(228,"observation-maturity","留存观察成熟度单独标注",["右删失","成熟度","固定观察截止"],
   "观察数据截止一月四日结束时，判断三日留存需要看注册日加三天是否已到一月四日。仅一月一日 cohort 已成熟，后两组必须标 pending，不能把未来尚未观察到的活跃误判为流失。",
   "SELECT signup,count(*),CASE WHEN date(signup,'+3 days')<='2026-01-04' THEN 'mature' ELSE 'pending' END FROM member GROUP BY signup ORDER BY signup;","2026-01-01|2|mature\n2026-01-02|1|pending\n2026-01-03|1|pending",
   ["未成熟 cohort 的零不是可比较留存值。","观察截止应来自数据完整性契约而不是系统时钟。"],
   ("统计具备完整三日观察的用户数。","注册加三天不晚于截止。","SELECT count(*) FROM member WHERE date(signup,'+3 days')<='2026-01-04';","2"),
   ("列出尚不能评估三日留存的 cohort。","使用严格晚于截止。","SELECT DISTINCT signup FROM member WHERE date(signup,'+3 days')>'2026-01-04' ORDER BY signup;","2026-01-02\n2026-01-03")),
 T(229,"recency-snapshot","固定快照日计算最近活跃间隔",["recency","固定快照","最近活跃"],
   "用一月五日减去各用户最后活跃日，用户 1 为 1 天，另外三人为 2 天。先求最近日期再算差，不能平均所有事件距今时间。对无事件用户应保留未知状态，不能假造最近活跃日。",
   "SELECT m.id,CAST(julianday('2026-01-05')-julianday(date(max(e.at))) AS INTEGER) FROM member m LEFT JOIN event e ON e.member_id=m.id GROUP BY m.id ORDER BY m.id;","1|1\n2|2\n3|2\n4|2",
   ["未来事件必须按快照截止排除。","recency 是观察指标，不自动等于永久流失。"],
   ("截至一月五日列出至少两天未活跃的用户。","按最大活跃日判断。","SELECT member_id FROM event GROUP BY member_id HAVING date(max(at))<='2026-01-03' ORDER BY member_id;","2\n3\n4"),
   ("列出最近活跃日恰好一月四日的用户数。","MAX 日期后外层计数。","SELECT count(*) FROM(SELECT member_id FROM event GROUP BY member_id HAVING date(max(at))='2026-01-04');","1")),
 T(230,"behavior-transition-counts","相邻事件转移统计",["LEAD","行为转移","序列分析"],
   "按用户时间与 id 排序，LEAD 得到下一个事件类型，再统计当前到下一个的转移次数。重复浏览也保留为真实转移，view→view 为 2 次。没有下一个事件的尾行被排除，转移数应等于总事件数减用户数。",
   "WITH r AS(SELECT kind,lead(kind) OVER(PARTITION BY member_id ORDER BY at,id) nxt FROM event) SELECT kind,nxt,count(*) FROM r WHERE nxt IS NOT NULL GROUP BY kind,nxt ORDER BY kind,nxt;","cart|pay|1\ncart|view|1\npay|view|2\nview|cart|2\nview|pay|1\nview|view|2",
   ["转移没有自动限制在同一会话，本题跨会话也计入。","没有稳定时间排序键就没有可靠相邻事件。"],
   ("核对相邻转移总数。","每用户最后一条没有后继。","SELECT count(*)-count(DISTINCT member_id) FROM event;","9"),
   ("只统计同用户紧邻的 view 到 pay 转移。","窗口后再过滤。","WITH r AS(SELECT kind,lead(kind) OVER(PARTITION BY member_id ORDER BY at,id) nxt FROM event) SELECT count(*) FROM r WHERE kind='view' AND nxt='pay';","1")),
 T(231,"cohort-conditional-pivot","条件聚合把短留存长表透视",["条件聚合","透视","活跃日"],
   "先去重用户日，以注册后偏移 0、1、2 为固定列分别计数。首日 cohort 为 2、1、1，第二日为 1、1、0，第三日为 1、0、0。后两组后续列的零须结合成熟度，不应直接比较为完整留存。",
   "WITH a AS(SELECT DISTINCT member_id,date(at) d FROM event),r AS(SELECT m.signup,CAST(julianday(a.d)-julianday(m.signup) AS INTEGER) off FROM member m JOIN a ON a.member_id=m.id) SELECT signup,sum(off=0),sum(off=1),sum(off=2) FROM r GROUP BY signup ORDER BY signup;","2026-01-01|2|1|1\n2026-01-02|1|1|0\n2026-01-03|1|0|0",
   ["固定透视列只适合有限且已定义的偏移集合。","需要输出完全静默 cohort 时应以注册 cohort 表左连接。"],
   ("计算首日 cohort 偏移二日活跃率。","一月三日只有用户 2。","SELECT round(100.0*sum(EXISTS(SELECT 1 FROM event e WHERE e.member_id=m.id AND date(e.at)=date(signup,'+2 days')))/count(*),1) FROM member m WHERE signup='2026-01-01';","50.0"),
   ("仅统计注册当天发生支付的不同用户。","事件日期等于 signup 且 kind=pay。","SELECT count(DISTINCT m.id) FROM member m JOIN event e ON e.member_id=m.id WHERE date(e.at)=m.signup AND e.kind='pay';","3")),
]
